INSERT INTO Modules (ModuleId, Title, BeltLevel, Description, DurationMinutes, Objectives, Prerequisites, DisplayOrder)
VALUES
(1, 'Quality Foundations', 'White Belt', 'Build the shared language of quality: where Six Sigma and Lean came from, why poor quality costs money, how customers define value, and why variation matters.', 90, 'Trace Six Sigma from Motorola and GE, and Lean from the Toyota Production System. | Define quality, prevention, appraisal, and failure costs, and calculate a simple COPQ example. | Turn customer wants into measurable critical-to-quality requirements. | Explain common and special cause variation and define a defect in plain language. | Describe the five DMAIC phases and the main question each phase answers.', 'None. Start here with zero prior knowledge.', 1),
(2, 'People, Waste, and First Projects', 'White Belt', 'Learn to see the eight wastes, understand who does what on a project, and adopt the culture and habits that make improvement stick.', 80, 'Identify the eight wastes in healthcare, retail, manufacturing, IT, banking, and education. | Explain the White, Yellow, Green, Black, and Master Black Belt roles and the sponsor role. | Describe respect for people, data-based decisions, and a no-blame learning culture. | Use a simple A3-style story to plan a small, safe improvement.', 'None. Start here with zero prior knowledge.', 2),
(3, 'Process Thinking', 'Yellow Belt', 'See work as a process with suppliers, inputs, steps, outputs, and customers. Learn to define process boundaries and draw what actually happens, not what people think happens.', 70, 'Explain inputs, outputs, boundaries, and the customer of a process. | Build a Suppliers, Inputs, Process, Outputs, Customers diagram. | Create a swimlane or flowchart and flag handoffs and decision points.', 'White Belt or equivalent basic quality awareness.', 3),
(4, 'DMAIC and Project Charters', 'Yellow Belt', 'Go deeper into DMAIC and learn the basic charter questions: why the project exists, what is in scope, how success is measured, and who is accountable.', 60, 'List the key activities and deliverables of each DMAIC phase. | Write a problem statement, goal, scope, team, and milestone plan.', 'White Belt or equivalent basic quality awareness.', 4),
(5, 'Data and Basic Charts', 'Yellow Belt', 'Collect trustworthy data and display it honestly. Practice check sheets, run charts, histograms, bar charts, and Pareto analysis.', 90, 'Distinguish continuous and discrete data and choose a suitable summary. | Design a simple form that makes data easy to record and verify. | Choose and interpret run charts, histograms, and bar charts. | Use the 80/20 rule to prioritize the few causes that create most of the problem.', 'White Belt or equivalent basic quality awareness.', 5),
(6, 'Root Cause and Lean Basics', 'Yellow Belt', 'Move from symptoms to causes using fishbone and 5 Whys, then remove everyday friction with 5S and basic Lean thinking.', 90, 'Brainstorm causes across people, process, equipment, materials, measurement, and environment. | Ask focused why questions until the actionable root cause is found. | Apply sort, set in order, shine, standardize, and sustain. | Use value, flow, pull, and perfection to reduce waiting and rework.', 'White Belt or equivalent basic quality awareness.', 6),
(7, 'People and Teamwork', 'Yellow Belt', 'Generate better ideas and help a team make decisions without losing the quiet voices or the evidence.', 50, 'Run silent idea generation and affinity grouping before judging ideas. | Define roles, ground rules, decision rules, and meeting habits for an improvement team.', 'White Belt or equivalent basic quality awareness.', 7),
(8, 'Define', 'Green Belt', 'Turn a vague complaint into a bounded project with a clear customer, measurable goal, and named stakeholders.', 90, 'Write a problem statement, goal, scope, business case, team, and timeline. | Map influence and interest and plan engagement. | Translate customer language into measurable CTQs and specifications.', 'Yellow Belt or equivalent process improvement experience.', 8),
(9, 'Measure', 'Green Belt', 'Build a trustworthy measurement system, describe the data, and compare process performance with customer specifications.', 240, 'Define what, where, when, who, and how to collect data. | Choose random, stratified, or systematic samples and avoid bias. | Run a Gage R&R and interpret %GRR and number of distinct categories. | Calculate and interpret mean, median, standard deviation, and range. | Use the 68-95-99.7 rule and check normality before capability analysis. | Convert defects and opportunities into DPMO and sigma level. | Calculate capability indices and explain the difference between potential and actual capability.', 'Yellow Belt or equivalent process improvement experience.', 9),
(10, 'Analyze', 'Green Belt', 'Use graphs, root cause tools, risk analysis, and statistical tests to separate real causes from noise.', 240, 'Select histograms, box plots, run charts, and scatter plots for the question. | Combine fishbone, 5 Whys, stratification, and process observation. | Score severity, occurrence, and detection and prioritize failure modes. | Form null and alternative hypotheses and interpret p-values correctly. | Measure the strength and direction of a linear relationship. | Fit a line, interpret slope and R-squared, and check residuals. | Compare means across three or more groups and read the F-test.', 'Yellow Belt or equivalent process improvement experience.', 10),
(11, 'Improve', 'Green Belt', 'Choose solutions with evidence, test them safely, mistake-proof the process, and begin designing experiments.', 150, 'Use impact, effort, risk, and cost to choose among candidate solutions. | Design a small trial with clear success measures and a rollback plan. | Add mistake-proofing devices or checks that prevent or detect errors. | Apply flow, pull, standard work, and quick changeover thinking. | Explain factors, levels, responses, and why experiments beat one-factor tests.', 'Yellow Belt or equivalent process improvement experience.', 11),
(12, 'Control', 'Green Belt', 'Keep the gains by monitoring the process, documenting the new standard, and assigning clear ownership.', 120, 'Select X-bar/R, I-MR, p, np, c, or u charts and apply basic rules. | Document metrics, sampling, reactions, and owners. | Write usable standard work and train to it.', 'Yellow Belt or equivalent process improvement experience.', 12),
(13, 'Project Management and Software', 'Green Belt', 'Run the project professionally and use Excel or Minitab for the core analyses.', 120, 'Plan tasks, manage risks, communicate status, and close the project. | Use descriptive statistics, control charts, capability, and t-tests in software.', 'Yellow Belt or equivalent process improvement experience.', 13),
(14, 'Probability and Inference', 'Black Belt', 'Build the statistical foundation for advanced decision-making: distributions, sampling, confidence, power, and the full hypothesis testing toolkit.', 300, 'Recognize normal, binomial, Poisson, exponential, and Weibull patterns. | Explain why sample means behave predictably. | Interpret interval estimates for means, proportions, and differences. | Balance alpha, beta, effect size, and sample size. | Select a test from the data type, number of groups, and assumptions. | Run one-sample, two-sample, and paired t-tests. | Run one-way and two-way ANOVA and interpret interactions. | Use Mann-Whitney, Kruskal-Wallis, and sign tests when assumptions fail. | Test independence and goodness of fit for categorical data.', 'Green Belt certification and completion of at least one DMAIC project.', 14),
(15, 'Measurement Systems', 'Black Belt', 'Extend MSA to pass/fail and categorical judgments, and understand calibration and uncertainty.', 120, 'Run attribute agreement analysis and interpret kappa. | Separate calibration, bias, linearity, and uncertainty.', 'Green Belt certification and completion of at least one DMAIC project.', 15),
(16, 'Regression and Modeling', 'Black Belt', 'Model relationships with multiple predictors and binary outcomes, then check whether the model is trustworthy.', 180, 'Interpret coefficients, adjusted R-squared, and overall model tests. | Model yes/no outcomes with odds ratios. | Check residuals, leverage, influence, and lack of fit. | Detect correlated predictors and choose a parsimonious model.', 'Green Belt certification and completion of at least one DMAIC project.', 16),
(17, 'Design of Experiments', 'Black Belt', 'Design efficient experiments, screen many factors, optimize responses, and make designs robust to noise.', 240, 'Design and analyze a full factorial with main effects and interactions. | Screen many factors with resolution III, IV, and V designs. | Protect experiments from nuisance variables. | Find optimum settings with central composite or Box-Behnken designs. | Reduce sensitivity to noise using control and noise factors.', 'Green Belt certification and completion of at least one DMAIC project.', 17),
(18, 'Advanced SPC and Capability', 'Black Belt', 'Monitor complex processes with advanced charts and handle capability when data are not normal or runs are short.', 150, 'Use CUSUM, EWMA, and multivariate charts appropriately. | Transform data or fit a distribution before calculating capability. | Monitor small batches with standardized or target charts.', 'Green Belt certification and completion of at least one DMAIC project.', 18),
(19, 'Lean and DFSS', 'Black Belt', 'Integrate Lean flow tools with Six Sigma and design new processes right the first time with DMADV, QFD, and Kano.', 240, 'Combine waste reduction and variation reduction in one strategy. | Map material and information flow and calculate lead time. | Improve equipment reliability with autonomous and planned maintenance. | Reduce changeover time by separating internal and external work. | Document the current best method with takt, sequence, and inventory. | Create a self-explaining, self-cleaning workplace. | Define, Measure, Analyze, Design, and Verify a new process or product. | Translate customer needs into design requirements with the House of Quality. | Classify features as basic, performance, or delighter.', 'Green Belt certification and completion of at least one DMAIC project.', 19),
(20, 'Leadership and Finance', 'Black Belt', 'Lead complex change, build project pipelines, prove financial benefit, and develop other belts.', 180, 'Use action priority, risk review, and integration with control plans. | Use a structured approach to build awareness, desire, knowledge, ability, and reinforcement. | Lead cross-functional teams, manage conflict, and make decisions. | Prioritize projects by impact, feasibility, risk, and strategic fit. | Build a benefit case with hard and soft savings. | Coach Green Belts and review project logic and statistics.', 'Green Belt certification and completion of at least one DMAIC project.', 20),
(21, 'Strategy Deployment', 'Master Black Belt', 'Connect improvement work to strategy through Hoshin Kanri, governance, portfolio selection, and validated financial benefits.', 240, 'Cascade strategic objectives into annual improvement priorities. | Use catchball to align goals, resources, and measures. | Design steering committees, review cadence, and escalation paths. | Balance impact, risk, capacity, and strategic fit. | Verify hard savings, avoid double counting, and track realization.', 'Black Belt certification and a track record of leading complex projects.', 21),
(22, 'Coaching and Consulting', 'Master Black Belt', 'Develop belts and leaders through coaching, mentoring, statistical consulting, and training design.', 180, 'Use questions, observation, and feedback to improve project thinking. | Build a pipeline of belts and subject-matter experts. | Diagnose analysis problems and recommend defensible methods. | Design practice-based curricula with assessment and transfer.', 'Black Belt certification and a track record of leading complex projects.', 22),
(23, 'Enterprise Transformation', 'Master Black Belt', 'Scale improvement across the enterprise with DFSS, change management, culture, balanced scorecards, and benchmarking.', 240, 'Deploy design methods across product, service, and process development. | Use change models, stakeholder plans, and reinforcement. | Make improvement, respect, and data-based decisions part of daily work. | Connect financial, customer, process, and learning measures. | Compare performance with best-in-class processes and adapt practices.', 'Black Belt certification and a track record of leading complex projects.', 23),
(24, 'Analytics and Industry 4.0', 'Master Black Belt', 'Integrate modern analytics, automation, and data governance into improvement work.', 120, 'Use sensors, dashboards, predictive models, and automation. | Protect privacy, ensure data quality, and use analytics responsibly.', 'Black Belt certification and a track record of leading complex projects.', 24),
(25, 'Standards and Certification', 'Master Black Belt', 'Understand the standards and ethical expectations behind certification and deployment.', 150, 'Explain the ISO standard for Six Sigma methods and roles. | Compare certification bodies, BoKs, and exam expectations. | Apply truthfulness, competence, confidentiality, and conflict-of-interest rules.', 'Black Belt certification and a track record of leading complex projects.', 25),
(26, 'Leadership and Value', 'Master Black Belt', 'Lead a deployment, prove value, and sustain improvement beyond individual projects.', 180, 'Lead leaders through resistance, politics, and competing priorities. | Track costs, benefits, cash flow, and value over time. | Build a deployment roadmap, governance model, and measurement plan.', 'Black Belt certification and a track record of leading complex projects.', 26);
