(20, 'B7.3', 3, 'Team Leadership', 'Lead cross-functional teams, manage conflict, and make decisions.'),
(20, 'B7.4', 4, 'Project Selection', 'Prioritize projects by impact, feasibility, risk, and strategic fit.'),
(20, 'B7.5', 5, 'Financial Analysis (COPQ, ROI)', 'Build a benefit case with hard and soft savings.'),
(20, 'B7.6', 6, 'Mentoring', 'Coach Green Belts and review project logic and statistics.'),
(21, 'M1.1', 1, 'Hoshin Kanri', 'Cascade strategic objectives into annual improvement priorities.'),
(21, 'M1.2', 2, 'Strategy Deployment and Catchball', 'Use catchball to align goals, resources, and measures.'),
(21, 'M1.3', 3, 'Program Governance', 'Design steering committees, review cadence, and escalation paths.'),
(21, 'M1.4', 4, 'Project Portfolio Selection', 'Balance impact, risk, capacity, and strategic fit.'),
(21, 'M1.5', 5, 'Financial Validation', 'Verify hard savings, avoid double counting, and track realization.'),
