(22, 'M2.2', 2, 'Mentoring and Capability Building', 'Build a pipeline of belts and subject-matter experts.'),
(22, 'M2.3', 3, 'Statistical Consulting', 'Diagnose analysis problems and recommend defensible methods.'),
(22, 'M2.4', 4, 'Training Design', 'Design practice-based curricula with assessment and transfer.'),
(23, 'M3.1', 1, 'Enterprise DFSS', 'Deploy design methods across product, service, and process development.'),
(23, 'M3.2', 2, 'Organizational Change', 'Use change models, stakeholder plans, and reinforcement.'),
(23, 'M3.3', 3, 'Culture Building', 'Make improvement, respect, and data-based decisions part of daily work.'),
(23, 'M3.4', 4, 'Balanced Scorecard', 'Connect financial, customer, process, and learning measures.'),
(23, 'M3.5', 5, 'Benchmarking', 'Compare performance with best-in-class processes and adapt practices.'),
(24, 'M4.1', 1, 'Analytics and Industry 4.0', 'Use sensors, dashboards, predictive models, and automation.'),
(24, 'M4.2', 2, 'Data Governance and Ethics', 'Protect privacy, ensure data quality, and use analytics responsibly.'),
