(25, 'M5.2', 2, 'ASQ and IASSC Standards', 'Compare certification bodies, BoKs, and exam expectations.'),
(25, 'M5.3', 3, 'Certification and Ethics', 'Apply truthfulness, competence, confidentiality, and conflict-of-interest rules.'),
